/* compat.h — lo que la DriverLib (escrita para las cabeceras de CCS) pregunta y
 * las de msp430-elf-gcc (generadas, __AUTOGENERATED__) llaman de otra manera;
 * se incluye antes de todo (-include) al compilar la ROM */
#ifndef ROM_COMPAT_H
#define ROM_COMPAT_H
#define __MSP430_HAS_FRAM__
#define __MSP430_HAS_PMM_FRAM__
#define __MSP430_HAS_EUSCI_Ax__
#define __MSP430_HAS_EUSCI_Bx__
#define __MSP430_HAS_ECOMPx__
#define __MSP430_HAS_TxB7__
#define __MSP430_HAS_SACx_CONFIG_3__
#include <msp430.h>
#include "msp430fr2xx_4xxgeneric.h"
#include "inc/version.h"
/* Los nombres de CCS que faltan: la base de la FRAM y de los Timer_B, y los
 * desplazamientos genéricos del eCOMP (los mismos que el CP0) */
#define FRAM_BASE      FRCTL_BASE
#define TIMER_B0_BASE  TB0_BASE
#define TIMER_B1_BASE  TB1_BASE
#define TIMER_B2_BASE  TB2_BASE
#define TIMER_B3_BASE  TB3_BASE
#define OFS_CPCTL0     OFS_CP0CTL0
#define OFS_CPCTL1     OFS_CP0CTL1
#define OFS_CPINT      OFS_CP0INT
#define OFS_CPIV       OFS_CP0IV
#define OFS_CPDACCTL   OFS_CP0DACCTL
#define OFS_CPDACDATA  OFS_CP0DACDATA
#endif
